from collections import Counter

def find_anagrams(s, p):
    result = []
    if len(s) < len(p):
        return result
    p_count = Counter(p)
    s_count = Counter()
    left = 0
    for right in range(len(s)):
        s_count[s[right]] += 1
        if right - left + 1 > len(p):
            s_count[s[left]] -= 1
            if s_count[s[left]] == 0:
                del s_count[s[left]]
            left += 1
        if s_count == p_count:
            result.append(left)
    return result

