import sys

def min_window(s, t):
    if not s or not t:
        return ""
    need = {}
    for ch in t:
        need[ch] = need.get(ch, 0) + 1
    left = 0
    right = 0
    formed = 0
    required = len(need)
    window = {}
    min_len = float('inf')
    ans = ""
    while right < len(s):
        c = s[right]
        window[c] = window.get(c, 0) + 1
        if c in need and window[c] == need[c]:
            formed += 1
        while left <= right and formed == required:
            c_left = s[left]
            if right - left + 1 < min_len:
                min_len = right - left + 1
                ans = s[left:right+1]
            window[c_left] -= 1
            if c_left in need and window[c_left] < need[c_left]:
                formed -= 1
            left += 1
        right += 1
    return ans

