from functools import lru_cache

def solve():
    n = int(input())
    nums = list(map(int, input().split()))

    @lru_cache(None)
    def dfs(state):
        state = list(state)
        if len(state) == 1:
            return state
        best = None
        for i in range(len(state)-1):
            if state[i] == state[i+1]:
                new_state = state[:i] + [state[i]+1] + state[i+2:]
                res = dfs(tuple(new_state))
                if best is None or res < best:
                    best = res
        return best if best is not None else state
    result = dfs(tuple(nums))
    print(len(result))
    print(' '.join(map(str, result)))

