def find_kth(k, a, b):
    if not a:
        return b[k-1]
    if not b:
        return a[k-1]
    ia, ib = len(a)//2, len(b)//2
    if ia + ib + 2 > k:
        if a[ia] > b[ib]:
            return find_kth(k, a[:ia], b)
        else:
            return find_kth(k, a, b[:ib])
    else:
        if a[ia] > b[ib]:
            return find_kth(k - ib - 1, a, b[ib+1:])
        else:
            return find_kth(k - ia - 1, a[ia+1:], b)

