    def __init__(self, val=0, next=None, random=None):
        self.val = val
        self.next = next
        self.random = random

def copyRandomList(head):
    if not head:
        return None
    # 第一遍：创建新节点并插入原节点后面
    cur = head
    while cur:
        new_node = Node(cur.val)
        new_node.next = cur.next
        cur.next = new_node
        cur = new_node.next
    # 第二遍：复制 random 指针
    cur = head
    while cur:
        if cur.random:
            cur.next.random = cur.random.next
        cur = cur.next.next
    # 第三遍：分离两个链表
    cur = head
    new_head = head.next
    while cur:
        nxt = cur.next
        cur.next = nxt.next
        if nxt.next:
            nxt.next = nxt.next.next
        cur = cur.next
    return new_head

