# 使用线段树维护区间最大最小值
class SegmentTree:
    def __init__(self, data):
        self.n = len(data)
        self.max_tree = [0] * (4 * self.n)
        self.min_tree = [0] * (4 * self.n)
        self._build(1, 0, self.n - 1, data)

    def _build(self, node, l, r, data):
        if l == r:
            self.max_tree[node] = self.min_tree[node] = data[l]
            return
        mid = (l + r) // 2
        self._build(node*2, l, mid, data)
        self._build(node*2+1, mid+1, r, data)
        self.max_tree[node] = max(self.max_tree[node*2], self.max_tree[node*2+1])
        self.min_tree[node] = min(self.min_tree[node*2], self.min_tree[node*2+1])

    def update(self, idx, value):
        self._update(1, 0, self.n-1, idx, value)

    def _update(self, node, l, r, idx, value):
        if l == r:
            self.max_tree[node] = self.min_tree[node] = value
            return
        mid = (l + r) // 2
        if idx <= mid:
            self._update(node*2, l, mid, idx, value)
        else:
            self._update(node*2+1, mid+1, r, idx, value)
        self.max_tree[node] = max(self.max_tree[node*2], self.max_tree[node*2+1])
        self.min_tree[node] = min(self.min_tree[node*2], self.min_tree[node*2+1])

    def query(self, ql, qr):
        max_val, min_val = self._query(1, 0, self.n-1, ql, qr)
        return max_val - min_val

    def _query(self, node, l, r, ql, qr):
        if ql <= l and r <= qr:
            return self.max_tree[node], self.min_tree[node]
        mid = (l + r) // 2
        if qr <= mid:
            return self._query(node*2, l, mid, ql, qr)
        elif ql > mid:
            return self._query(node*2+1, mid+1, r, ql, qr)
        else:
            max1, min1 = self._query(node*2, l, mid, ql, mid)
            max2, min2 = self._query(node*2+1, mid+1, r, mid+1, qr)
            return max(max1, max2), min(min1, min2)

def main():
    data = sys.stdin.read().split()
