class Node:
    def __init__(self, sum=0, lmax=0, rmax=0, tmax=0):
        self.sum = sum
        self.lmax = lmax
        self.rmax = rmax
        self.tmax = tmax

def merge(left, right):
    node = Node()
    node.sum = left.sum + right.sum
    node.lmax = max(left.lmax, left.sum + right.lmax)
    node.rmax = max(right.rmax, right.sum + left.rmax)
    node.tmax = max(left.tmax, right.tmax, left.rmax + right.lmax)
    return node

