    if l == r:
        tree[idx] = Node(a[l-1], a[l-1], a[l-1], a[l-1])
        return
    mid = (l+r)//2
    build(idx*2, l, mid)
    build(idx*2+1, mid+1, r)
    tree[idx] = merge(tree[idx*2], tree[idx*2+1])

