# 使用线段树维护每个节点：未匹配左括号数a，未匹配右括号数b，最大匹配对数ans
# 合并时：ans = left.ans + right.ans + min(left.a, right.b)
# 翻转操作：交换a和b，并ans不变？实际翻转后，a和b互换，ans不变，但需注意整体翻转后a和b互换
# 懒标记记录是否翻转
import sys

class Node:
    __slots__ = ('a','b','ans')
    def __init__(self, a=0, b=0, ans=0):
        self.a = a
        self.b = b
        self.ans = ans

def merge(left, right):
    m = min(left.a, right.b)
    return Node(left.a + right.a - m, left.b + right.b - m, left.ans + right.ans + m)

def main():
    input = sys.stdin.readline
    n, m = map(int, input().split())
    s = input().strip()
    size = 1
    while size < n:
        size <<= 1
    tree = [Node() for _ in range(2*size)]
    lazy = [0]*(2*size)
    # 建树
    for i in range(n):
        if s[i] == '(':
            tree[size+i] = Node(1,0,0)
        else:
            tree[size+i] = Node(0,1,0)
    for i in range(size-1,0,-1):
        tree[i] = merge(tree[2*i], tree[2*i+1])
    def apply(idx):
        tree[idx].a, tree[idx].b = tree[idx].b, tree[idx].a
        lazy[idx] ^= 1
    def push(idx):
        if lazy[idx]:
            apply(2*idx)
            apply(2*idx+1)
            lazy[idx]=0
    def update(l, r, idx=1, nl=1, nr=size):
        if l<=nl and nr<=r:
            apply(idx)
            return
        push(idx)
        mid=(nl+nr)//2
        if l<=mid: update(l,r,2*idx,nl,mid)
        if r>mid: update(l,r,2*idx+1,mid+1,nr)
        tree[idx]=merge(tree[2*idx],tree[2*idx+1])
    def query(l,r,idx=1,nl=1,nr=size):
        if l<=nl and nr<=r:
            return tree[idx]
        push(idx)
        mid=(nl+nr)//2
        if r<=mid: return query(l,r,2*idx,nl,mid)
        if l>mid: return query(l,r,2*idx+1,mid+1,nr)
        return merge(query(l,r,2*idx,nl,mid), query(l,r,2*idx+1,mid+1,nr))
    out=[]
