# 区间DP，dp[l][r]表示将区间[l,r]完全合并后得到的单个值（如果可能），或者-1表示不能完全合并成单个值
# 转移：dp[l][r] = x if 存在k使得dp[l][k]==dp[k+1][r]==y 且 x=y+1，或者区间长度为1时dp[l][l]=a[l]
# 最终答案：用另一个dp2[i]表示前缀i的最小长度，转移dp2[i]=min(dp2[j]+1) if dp[j+1][i]!=-1
import sys

def main():
    input = sys.stdin.readline
    n = int(input())
    a = list(map(int,input().split()))
    dp = [[-1]*(n+1) for _ in range(n+1)]
    for i in range(n):
        dp[i][i] = a[i]
    for length in range(2,n+1):
        for l in range(n-length+1):
            r = l+length-1
            for k in range(l,r):
                if dp[l][k]!=-1 and dp[k+1][r]!=-1 and dp[l][k]==dp[k+1][r]:
                    dp[l][r] = dp[l][k]+1
                    break
    f = [float('inf')]*(n+1)
    f[0]=0
    for i in range(1,n+1):
        for j in range(i):
            if dp[j][i-1]!=-1:
                f[i] = min(f[i], f[j]+1)
    print(f[n])

