    main()

# 本题操作3需要暴力开方，但每个数最多开方约loglog次变为1，所以可以维护每个位置是否全为0/1，用并查集跳过。
# 线段树维护区间和，对于操作3，如果区间内所有数都<=1则跳过，否则递归到叶子进行开方。
# 由于每个数最多被开方约6次（1e9 -> 1），所以总复杂度O(m log n * 常数)
import sys
import math

class SegTree:
    def __init__(self, n):
        self.n = n
        self.sum = [0]*(4*n)
        self.maxv = [0]*(4*n)
    def build(self, idx, l, r):
        if l==r:
            self.sum[idx]=0
            self.maxv[idx]=0
            return
        mid=(l+r)//2
        self.build(idx*2,l,mid)
        self.build(idx*2+1,mid+1,r)
        self.sum[idx]=0
        self.maxv[idx]=0
    def update_add(self, idx, l, r, ql, qr, x):
        if ql<=l and r<=qr:
            self.sum[idx] += x*(r-l+1)
            self.maxv[idx] += x
            return
        mid=(l+r)//2
        if ql<=mid: self.update_add(idx*2,l,mid,ql,qr,x)
        if qr>mid: self.update_add(idx*2+1,mid+1,r,ql,qr,x)
        self.sum[idx]=self.sum[idx*2]+self.sum[idx*2+1]
        self.maxv[idx]=max(self.maxv[idx*2], self.maxv[idx*2+1])
    def update_sqrt(self, idx, l, r, ql, qr):
        if self.maxv[idx] <= 1:
            return
        if l==r:
            val = int(math.isqrt(self.sum[idx]))
            self.sum[idx] = val
            self.maxv[idx] = val
            return
        mid=(l+r)//2
        if ql<=mid: self.update_sqrt(idx*2,l,mid,ql,qr)
        if qr>mid: self.update_sqrt(idx*2+1,mid+1,r,ql,qr)
        self.sum[idx]=self.sum[idx*2]+self.sum[idx*2+1]
        self.maxv[idx]=max(self.maxv[idx*2], self.maxv[idx*2+1])
    def query(self, idx, l, r, ql, qr):
        if ql<=l and r<=qr:
            return self.sum[idx]
        mid=(l+r)//2
        ans=0
        if ql<=mid: ans+=self.query(idx*2,l,mid,ql,qr)
        if qr>mid: ans+=self.query(idx*2+1,mid+1,r,ql,qr)
        return ans

def main():
    input = sys.stdin.readline
    n,m = map(int,input().split())
    st = SegTree(n)
    st.build(1,1,n)
    out=[]
    for _ in range(m):
        op = list(map(int,input().split()))
        if op[0]==1:
            _,l,r,x = op
            st.update_add(1,1,n,l,r,x)
        elif op[0]==2:
            _,l,r = op
            out.append(str(st.query(1,1,n,l,r)))
        else:
            _,l,r = op
            st.update_sqrt(1,1,n,l,r)
    sys.stdout.write('\n'.join(out))

if __name__=='__main__':
    main()

