import sys

def solve():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))
    # dp[l][r] = minimum length after merging subarray a[l..r]
    # also need to know the resulting value if fully merged? We can store possible values.
    # Use interval DP: dp[l][r] = set of possible resulting values if fully merged into one element.
    # Then answer is min over partitions.
    # Since n<=500, a[i]<=40, value can go up to 40+log2(n) about 50.
    # We can use set of int.
    from functools import lru_cache
    @lru_cache(None)
    def can_merge(l, r):
        # returns set of possible values if a[l..r] can be fully merged into one element
        if l == r:
            return {a[l]}
        res = set()
        for k in range(l, r):
            left = can_merge(l, k)
            right = can_merge(k+1, r)
            for x in left:
                for y in right:
                    if x == y:
                        res.add(x+1)
        return res
    # dp[i] = min length for prefix up to i
    dp = [float('inf')]*(n+1)
    dp[0] = 0
    for i in range(1, n+1):
        for j in range(i):
            if can_merge(j, i-1):  # can merge a[j..i-1] into one
                dp[i] = min(dp[i], dp[j] + 1)
    print(dp[n])

if __name__ == '__main__':
    solve()

