import sys

class SegmentTree:
    def __init__(self, data):
        self.n = len(data)
        self.size = 1
        while self.size < self.n:
            self.size <<= 1
        self.min_pref = [0]*(2*self.size)
        self.total = [0]*(2*self.size)
        for i in range(self.n):
            val = 1 if data[i]=='(' else -1
            self.min_pref[self.size+i] = val
            self.total[self.size+i] = val
        for i in range(self.size-1,0,-1):
            self.total[i] = self.total[2*i] + self.total[2*i+1]
            self.min_pref[i] = min(self.min_pref[2*i], self.total[2*i] + self.min_pref[2*i+1])
    def update(self, pos, val):
        i = self.size + pos
        self.total[i] = val
        self.min_pref[i] = val
        i //= 2
        while i:
            self.total[i] = self.total[2*i] + self.total[2*i+1]
            self.min_pref[i] = min(self.min_pref[2*i], self.total[2*i] + self.min_pref[2*i+1])
            i //= 2
    def query(self):
        return self.total[1] == 0 and self.min_pref[1] >= 0

