from collections import deque

def solve():
    data = sys.stdin.read().split()
    n = int(data[0])
    level = list(map(int, data[1:1+n]))

    # 构建树节点
    nodes = []
    for val in level:
        if val == -1:
            nodes.append(None)
        else:
            nodes.append({'val': val, 'left': None, 'right': None})

    # 用队列构建父子关系
    q = deque()
    q.append(nodes[0])
    idx = 1
    while q and idx < n:
        node = q.popleft()
        if node is None:
            continue
        if idx < n:
            node['left'] = nodes[idx]
            q.append(nodes[idx])
            idx += 1
        if idx < n:
            node['right'] = nodes[idx]
            q.append(nodes[idx])
            idx += 1

    root = nodes[0]
    if root is None:
        print()
        return

    result = []
    # 收集左边界（不包括叶节点）
    def is_leaf(node):
        return node is not None and node['left'] is None and node['right'] is None

    # 左边界
    cur = root
    while cur:
        if not is_leaf(cur):
            result.append(cur['val'])
        if cur['left']:
            cur = cur['left']
        elif cur['right']:
            cur = cur['right']
        else:
            break

    # 收集叶节点（从左到右）
    leaves = []
    def dfs(node):
        if node is None:
            return
        if is_leaf(node):
            leaves.append(node['val'])
            return
        dfs(node['left'])
        dfs(node['right'])
    dfs(root)
    # 叶节点中排除边界上的（左边界和右边界可能包含叶节点，但题目说叶节点单独输出，且左边界不包括叶节点，所以这里直接输出所有叶节点）
    result.extend(leaves)

    # 右边界（不包括根和叶节点）
    right_boundary = []
    cur = root['right'] if root['right'] else None
    while cur:
        if not is_leaf(cur):
            right_boundary.append(cur['val'])
        if cur['right']:
            cur = cur['right']
        elif cur['left']:
            cur = cur['left']
        else:
            break
    result.extend(reversed(right_boundary))

    print(' '.join(map(str, result)))

