from functools import lru_cache

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    pre = list(map(int, data[1:1+n]))
    ino = list(map(int, data[1+n:1+2*n]))

    @lru_cache(None)
    def get_post(pre_l, pre_r, in_l, in_r):
        # 返回可能的后续序列列表（list of tuple）
        if pre_l > pre_r:
            return [()]
        root = pre[pre_l]
        # 在中序中找root可能出现的位置
        results = []
        for idx in range(in_l, in_r+1):
            if ino[idx] == root:
                left_len = idx - in_l
                right_len = in_r - idx
                # 检查先序中左子树和右子树的长度是否一致
                # 左子树先序范围：pre_l+1 到 pre_l+left_len
                # 右子树先序范围：pre_l+left_len+1 到 pre_r
                # 需要保证右子树的先序长度 = right_len
                if pre_l+left_len+1+right_len-1 == pre_r:
                    left_posts = get_post(pre_l+1, pre_l+left_len, in_l, idx-1)
                    right_posts = get_post(pre_l+left_len+1, pre_r, idx+1, in_r)
                    for lp in left_posts:
                        for rp in right_posts:
                            results.append(lp + rp + (root,))
        return results

    posts = get_post(0, n-1, 0, n-1)
    if not posts:
        print("NO")
        return
    # 去重并排序
    unique = sorted(set(posts))
    for p in unique:
        print(' '.join(map(str, p)))

