def generate(pre, ino):
    if not pre:
        return [""]
    if len(pre) != len(ino):
        return []
    # 根为pre[0]
    root = pre[0]
    # 在中序中找到所有root的位置
    positions = [i for i, c in enumerate(ino) if c == root]
    res = []
    for pos in positions:
        left_in = ino[:pos]
        right_in = ino[pos+1:]
        # 先序中，左子树的先序长度等于左子树节点数，但节点值可能重复，需要划分。
        # 由于有重复，无法直接划分，需枚举左子树长度。
        # 左子树节点数必须等于len(left_in)，但先序中前len(left_in)个可能包含右子树节点？不，先序中根后是左子树先序，但左子树节点集合与left_in一致，所以我们可以从pre[1:]中选出所有属于left_in的节点，但顺序要保持先序。
        # 但因为有重复，需要递归尝试。
        # 简单方法：枚举左子树节点数k，从0到len(pre)-1，但需保证pre[1:1+k]中的节点集合与left_in一致（考虑重复）。
        for k in range(len(pre)):
            left_pre = pre[1:1+k]
            right_pre = pre[1+k:]
            # 检查left_pre的字符集合是否与left_in一致（考虑多重集）
            from collections import Counter
            if Counter(left_pre) == Counter(left_in) and Counter(right_pre) == Counter(right_in):
                left_results = generate(left_pre, left_in)
                right_results = generate(right_pre, right_in)
                for l in left_results:
                    for r in right_results:
                        res.append(l + r + root)
    return list(set(res))

