import sys
from collections import deque

class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def parse(s):
    if not s:
        return None
    # 找第一个 '(' 的位置
    i = 0
    while i < len(s) and s[i] != '(':
        i += 1
    if i == len(s):
        # 没有子树，整个是叶子节点
        return Node(int(s))
    val = int(s[:i])
    node = Node(val)
    # 找到匹配的括号
    start = i
    depth = 0
    for j in range(i, len(s)):
        if s[j] == '(':
            depth += 1
        elif s[j] == ')':
            depth -= 1
            if depth == 0:
                # 括号结束
                inner = s[start+1:j]
                # 分割左右孩子，逗号可能在括号内，所以需要扫描
                # 找到逗号在深度0处
                k = start+1
                depth2 = 0
                comma_pos = -1
                while k < j:
                    if s[k] == '(':
                        depth2 += 1
                    elif s[k] == ')':
                        depth2 -= 1
                    elif s[k] == ',' and depth2 == 0:
                        comma_pos = k
                        break
                    k += 1
                if comma_pos == -1:
                    # 只有一个孩子，视为左孩子
                    left_str = inner
                    node.left = parse(left_str)
                else:
                    left_str = inner[:comma_pos-start-1]
                    right_str = inner[comma_pos-start:]
                    if left_str:
                        node.left = parse(left_str)
                    if right_str:
                        node.right = parse(right_str)
                break
    return node

def preorder(node):
    if not node:
        return []
    return [node.val] + preorder(node.left) + preorder(node.right)

def inorder(node):
    if not node:
        return []
    return inorder(node.left) + [node.val] + inorder(node.right)

def postorder(node):
    if not node:
        return []
    return postorder(node.left) + postorder(node.right) + [node.val]

def levelorder(node):
    if not node:
        return []
    q = deque([node])
    res = []
    while q:
        cur = q.popleft()
        res.append(cur.val)
        if cur.left:
            q.append(cur.left)
        if cur.right:
            q.append(cur.right)
    return res

