def longest_substring_with_k_repeats(s, k):
    max_len = 0
    max_unique = len(set(s))
    for target_unique in range(1, max_unique + 1):
        left = 0
        freq = [0] * 26
        unique = 0
        count_ge_k = 0
        for right in range(len(s)):
            idx = ord(s[right]) - 97
            if freq[idx] == 0:
                unique += 1
            freq[idx] += 1
            if freq[idx] == k:
                count_ge_k += 1
            while unique > target_unique:
                left_idx = ord(s[left]) - 97
                if freq[left_idx] == k:
                    count_ge_k -= 1
                freq[left_idx] -= 1
                if freq[left_idx] == 0:
                    unique -= 1
                left += 1
            if unique == target_unique and count_ge_k == unique:
                max_len = max(max_len, right - left + 1)
    return max_len

print(longest_substring_with_k_repeats(s, k))

