def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])
    nums = list(map(int, data[2:2+n]))
    qmax = deque()
    qmin = deque()
    left = 0
    ans = 0
    for right in range(n):
        while qmax and nums[qmax[-1]] <= nums[right]:
            qmax.pop()
        qmax.append(right)
        while qmin and nums[qmin[-1]] >= nums[right]:
            qmin.pop()
        qmin.append(right)
        while nums[qmax[0]] - nums[qmin[0]] > k:
            if qmax[0] == left:
                qmax.popleft()
            if qmin[0] == left:
                qmin.popleft()
            left += 1
        ans = max(ans, right - left + 1)
    print(ans)

