import sys
def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    if n == 0:
        print(0)
        return
    vals = list(map(int, data[1:1+n]))
    # 计算逆序数即可，因为相邻交换次数等于逆序数
    # 使用归并排序或树状数组计算逆序数
    # 这里用树状数组
    class BIT:
        def __init__(self, n):
            self.n = n
            self.tree = [0]*(n+1)
        def update(self, i, delta):
            while i <= self.n:
                self.tree[i] += delta
                i += i & (-i)
        def query(self, i):
            s = 0
            while i > 0:
                s += self.tree[i]
                i -= i & (-i)
            return s
    bit = BIT(n)
    inv = 0
    for i, v in enumerate(vals):
        # 统计比v大的已出现个数
        inv += i - bit.query(v)
        bit.update(v, 1)
    print(inv)
