import sys

def can_valid(s):
    n = len(s)
    if n % 2 == 1:
        return False
    # 检查当前是否合法
    bal = 0
    for ch in s:
        if ch == '(':
            bal += 1
        else:
            bal -= 1
        if bal < 0:
            break
    if bal == 0:
        return True
    # 尝试修改一个位置
    for i in range(n):
        t = list(s)
        t[i] = '(' if s[i] == ')' else ')'
        bal = 0
        ok = True
        for ch in t:
            if ch == '(':
                bal += 1
            else:
                bal -= 1
            if bal < 0:
                ok = False
                break
        if ok and bal == 0:
            return True
    return False

