import sys

def solve():
    input = sys.stdin.readline
    T = int(input())
    for _ in range(T):
        n, k = map(int, input().split())
        s = list(input().strip())
        # 当k为偶数时，只能交换奇偶位置上的字符；当k为奇数时，可以任意排列所有字符（因为可以生成任意置换）
        # 具体：若k为偶数，则位置奇偶性不变；若k为奇数，则奇偶性可互换，且可以任意排列（因为相邻交换可实现）
        # 但更准确：k为奇数时，可以任意排列整个字符串；k为偶数时，只能分别排列奇数位和偶数位
        # 要形成回文，需要左右对称字符相等，考虑奇偶位置
        if k % 2 == 1:
            # 可以任意排列，只需检查每个字符出现次数，至多一个奇数
            cnt = {}
            for ch in s:
                cnt[ch] = cnt.get(ch, 0) + 1
            odd = 0
            for c in cnt.values():
                if c % 2:
                    odd += 1
            print("YES" if odd <= 1 else "NO")
        else:
            # 奇数位和偶数位分别排列，要求各自能形成回文的一半？
            # 实际上，由于可以任意排列奇数位和偶数位，但最终回文要求位置i和n-1-i字符相同，且它们奇偶性相同（因为n-1-i与i奇偶性相同）
            # 所以只需要奇数位和偶数位各自字符多重集满足：每个字符出现次数为偶数（因为对称位置在同一集合）
            # 但注意n为奇数时中间位置单独，但中间位置属于奇数位或偶数位，需要出现次数为奇数允许一次
            odd_pos = [s[i] for i in range(0, n, 2)]
            even_pos = [s[i] for i in range(1, n, 2)]
            def check(arr):
                cnt = {}
                for ch in arr:
                    cnt[ch] = cnt.get(ch, 0) + 1
                odd_cnt = 0
                for c in cnt.values():
                    if c % 2:
                        odd_cnt += 1
                return odd_cnt <= 1
            print("YES" if check(odd_pos) and check(even_pos) else "NO")

if __name__ == '__main__':
    solve()

