import sys

class SegTree:
    def __init__(self, n):
        self.n = n
        self.maxv = [0]*(4*n)
        self.lazy = [0]*(4*n)

    def _push(self, idx):
        if self.lazy[idx] != 0:
            self.maxv[idx*2] += self.lazy[idx]
            self.lazy[idx*2] += self.lazy[idx]
            self.maxv[idx*2+1] += self.lazy[idx]
            self.lazy[idx*2+1] += self.lazy[idx]
            self.lazy[idx] = 0

    def _update(self, idx, l, r, ql, qr, v):
        if ql <= l and r <= qr:
            self.maxv[idx] += v
            self.lazy[idx] += v
            return
        self._push(idx)
        mid = (l+r)//2
        if ql <= mid:
            self._update(idx*2, l, mid, ql, qr, v)
        if qr > mid:
            self._update(idx*2+1, mid+1, r, ql, qr, v)
        self.maxv[idx] = max(self.maxv[idx*2], self.maxv[idx*2+1])

    def _query(self, idx, l, r, ql, qr):
        if ql <= l and r <= qr:
            return self.maxv[idx]
        self._push(idx)
        mid = (l+r)//2
        res = -10**18
        if ql <= mid:
            res = max(res, self._query(idx*2, l, mid, ql, qr))
        if qr > mid:
            res = max(res, self._query(idx*2+1, mid+1, r, ql, qr))
        return res

    def update(self, l, r, v):
        self._update(1, 1, self.n, l, r, v)

    def query(self, l, r):
        return self._query(1, 1, self.n, l, r)

def main():
    input = sys.stdin.readline
    n, m = map(int, input().split())
    seg = SegTree(n)
    out = []
    for _ in range(m):
        parts = input().split()
        if parts[0] == 'U':
            l, r, v = map(int, parts[1:])
            seg.update(l, r, v)
        else:
            l, r = map(int, parts[1:])
            out.append(str(seg.query(l, r)))
    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    main()

