def solve_correct():
    import sys
    from collections import deque
    input = sys.stdin.readline
    q = int(input())
    # 使用两个栈模拟双端队列：left_stack（队首）和right_stack（队尾）
    left = []  # 存储 (value, min_so_far)
    right = []  # 存储 (value, min_so_far)
    # 辅助函数
    def push_left(x):
        if left:
            left.append((x, min(x, left[-1][1])))
        else:
            left.append((x, x))
    def push_right(x):
        if right:
            right.append((x, min(x, right[-1][1])))
        else:
            right.append((x, x))
    def pop_left():
        # 如果left为空，将right全部倒入left
        if not left:
            while right:
                val, _ = right.pop()
                push_left(val)
        return left.pop()[0]
    def pop_right():
        if not right:
            while left:
                val, _ = left.pop()
                push_right(val)
        return right.pop()[0]
    def get_min():
        mins = []
        if left:
            mins.append(left[-1][1])
        if right:
            mins.append(right[-1][1])
        return min(mins) if mins else None

    res = []
