def parse(s):
    # 返回根节点和剩余索引
    if not s:
        return None
    root = {'val':s[0], 'left':None, 'right':None}
    i = 1
    if i < len(s) and s[i] == '(':
        # 解析左子树
        if s[i+1] == ',':
            # 左子树为空
            i += 1
        else:
            # 找到左子树的结束位置
            depth = 0
            j = i
            while j < len(s):
                if s[j] == '(':
                    depth += 1
                elif s[j] == ')':
                    depth -= 1
                    if depth == 0:
                        break
                j += 1
            left_str = s[i+1:j]
            root['left'] = parse(left_str)
            i = j
        # 现在i指向','或')'
        if i < len(s) and s[i] == ',':
            # 解析右子树
            if s[i+1] == ')':
                i += 1
            else:
                depth = 0
                j = i
                while j < len(s):
                    if s[j] == '(':
                        depth += 1
                    elif s[j] == ')':
                        depth -= 1
                        if depth == 0:
                            break
                    j += 1
                right_str = s[i+1:j]
                root['right'] = parse(right_str)
                i = j
        # 跳过')'
        i += 1
    return root

def preorder(node):
    if not node:
        return ''
    return node['val'] + preorder(node['left']) + preorder(node['right'])

def inorder(node):
    if not node:
        return ''
    return inorder(node['left']) + node['val'] + inorder(node['right'])

def postorder(node):
    if not node:
        return ''
    return postorder(node['left']) + postorder(node['right']) + node['val']

