def build(ino, post):
    if not ino:
        return None
    root_val = post[-1]
    idx = ino.index(root_val)
    root = {'val': root_val}
    root['left'] = build(ino[:idx], post[:idx])
    root['right'] = build(ino[idx+1:], post[idx:-1])
    return root

def level_order(root):
    if not root:
        return []
    q = deque([root])
    res = []
    while q:
        node = q.popleft()
        res.append(node['val'])
        if node['left']: q.append(node['left'])
        if node['right']: q.append(node['right'])
    return res

