def count_leaves(pre, ino, l1, r1, l2, r2):
    if l1 > r1:
        return 0
    root = pre[l1]
    idx = pos[root]
    left_len = idx - l2
    if l1 == r1:
        return 1
    return count_leaves(pre, ino, l1+1, l1+left_len, l2, idx-1) + count_leaves(pre, ino, l1+left_len+1, r1, idx+1, r2)

