        if s[i].isalpha():
            node = {'val': s[i], 'left': None, 'right': None}
            if stack:
                # 判断是左还是右，根据之前的状态
                pass
            # 简化：使用递归解析
            # 这里用递归函数
            return parse_rec(s, i)[0]
        i += 1

def parse_rec(s, idx):
    # 返回 (node, new_idx)
    if idx >= len(s):
        return None, idx
    if s[idx] == '(' or s[idx] == ',' or s[idx] == ')':
        return None, idx
    val = s[idx]
    node = {'val': val, 'left': None, 'right': None}
    idx += 1
    if idx < len(s) and s[idx] == '(':
        # 左子树
        left, idx = parse_rec(s, idx+1)
        node['left'] = left
        if idx < len(s) and s[idx] == ',':
            right, idx = parse_rec(s, idx+1)
            node['right'] = right
        if idx < len(s) and s[idx] == ')':
            idx += 1
    return node, idx

def main():
    s = sys.stdin.readline().strip()
    root, _ = parse_rec(s, 0)
    if not root:
        print()
        print(0)
        return
    # 层序遍历
    q = deque([root])
    order = []
    leaf_cnt = 0
    while q:
        node = q.popleft()
        order.append(node['val'])
        if node['left'] is None and node['right'] is None:
            leaf_cnt += 1
        if node['left']:
            q.append(node['left'])
        if node['right']:
            q.append(node['right'])
    print(' '.join(order))
    print(leaf_cnt)

