from collections import deque

def build_all(pre, ino):
    if not pre:
        return [None]
    root = pre[0]
    n = len(pre)
    results = []
    # 尝试所有可能的根位置
    for i in range(n):
        if ino[i] == root:
            left_ino = ino[:i]
            right_ino = ino[i+1:]
            left_len = len(left_ino)
            right_len = len(right_ino)
            if left_len + right_len != n-1:
                continue
            left_pre = pre[1:1+left_len]
            right_pre = pre[1+left_len:]
            # 检查左子树和右子树的字符集合是否匹配
            if set(left_pre) != set(left_ino) or set(right_pre) != set(right_ino):
                continue
            left_trees = build_all(left_pre, left_ino)
            right_trees = build_all(right_pre, right_ino)
            for lt in left_trees:
                for rt in right_trees:
                    results.append((root, lt, rt))
    return results

def level_order(tree):
    if tree is None:
        return []
    q = deque([tree])
    res = []
    while q:
        node = q.popleft()
        if node is None:
            continue
        res.append(node[0])
        if node[1] is not None:
            q.append(node[1])
        if node[2] is not None:
            q.append(node[2])
    return ''.join(res)

