import sys

def parse(s):
    # 递归解析，返回(节点值, 左子树, 右子树) 或 None
    if not s:
        return None
    # 找到第一个'('的位置
    i = 0
    while i < len(s) and s[i] != '(':
        i += 1
    if i == len(s):
        # 只有值
        return (int(s), None, None)
    val = int(s[:i])
    # 找到匹配的括号
    j = i
    cnt = 0
    while j < len(s):
        if s[j] == '(':
            cnt += 1
        elif s[j] == ')':
            cnt -= 1
            if cnt == 0:
                break
        j += 1
    inner = s[i+1:j]
    # 分割左右子树，逗号在顶层
    # 找逗号位置，考虑括号嵌套
    k = 0
    depth = 0
    comma = -1
    while k < len(inner):
        if inner[k] == '(':
            depth += 1
        elif inner[k] == ')':
            depth -= 1
        elif inner[k] == ',' and depth == 0:
            comma = k
            break
        k += 1
    if comma == -1:
        # 只有左子树？但合法输入可能只有左或右，但逗号必须有？题目保证合法，所以要么有逗号，要么没有子树？
        # 但可能没有逗号？例如"1(2)"表示只有左子树？但题目中括号内必须有逗号？通常表示法可能省略逗号？但题目示例中有逗号。这里我们处理：如果无逗号，则整个inner是左子树？或者右？按惯例，"1(2)"表示左子树2，右空。
        left_str = inner
        right_str = ''
    else:
        left_str = inner[:comma]
        right_str = inner[comma+1:]
    left = parse(left_str) if left_str else None
    right = parse(right_str) if right_str else None
    return (val, left, right)

def solve():
    s = sys.stdin.read().strip()
    if not s:
        return
    root = parse(s)
    # 层次遍历
    from collections import deque
    q = deque()
    q.append(root)
    res = []
    while q:
        node = q.popleft()
        if node is None:
            res.append('-1')
            continue
        res.append(str(node[0]))
        q.append(node[1])
        q.append(node[2])
    # 去掉末尾可能多余的-1？但题目要求输出完整层次，空节点用-1，直到最后一层？通常输出到最后一个非空节点，但这里要求输出所有？按照示例，输出到最后一个非空节点的下一层？看示例1：1 2 3 4 5 -1 6，最后是6，没有多余的-1。所以我们需要截断到最后一个非空节点。
    # 找到最后一个非-1的位置
    last = -1
    for i in range(len(res)-1, -1, -1):
        if res[i] != '-1':
            last = i
            break
    if last == -1:
        print('')
    else:
        print(' '.join(res[:last+1]))

if __name__ == '__main__':
    solve()

