def solve():
    n, m = map(int, input().split())
    graph = [[] for _ in range(n+1)]
    for _ in range(m):
        u, v, w = map(int, input().split())
        graph[u].append((v, w))
    INF = 10**18
    # dist[node][bit] = (min_cost, min_edges)
    # 使用BFS+DP，因为异或性质，状态较多，但N小，w范围大，无法按位DP，使用SPFA或Dijkstra变体
    # 由于异或不是单调的，不能用普通Dijkstra，使用SPFA
    dist = {}
    dist[(1, 0)] = (0, 0)
    from collections import deque
    q = deque([(1, 0)])
    inq = set([(1, 0)])
    while q:
        u, xor_val = q.popleft()
        inq.remove((u, xor_val))
        d, e = dist[(u, xor_val)]
        for v, w in graph[u]:
            new_xor = xor_val ^ w
            new_d = d + 1
            new_e = e + 1
            if (v, new_xor) not in dist or (new_d, new_e) < (dist[(v, new_xor)][0], dist[(v, new_xor)][1]):
                dist[(v, new_xor)] = (new_d, new_e)
                if (v, new_xor) not in inq:
                    q.append((v, new_xor))
                    inq.add((v, new_xor))
    ans_cost = INF
    ans_edges = INF
    for (node, xor_val), (d, e) in dist.items():
        if node == n:
            if d < ans_cost or (d == ans_cost and e < ans_edges):
                ans_cost = d
                ans_edges = e
    if ans_cost == INF:
        print(-1, -1)
    else:
        print(ans_cost, ans_edges)

