import sys

def bellman_ford(n, edges, s):
    dist = [float('inf')] * (n+1)
    dist[s] = 0
    for _ in range(n-1):
        updated = False
        for u, v, w in edges:
            if dist[u] != float('inf') and dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                updated = True
            if dist[v] != float('inf') and dist[v] + w < dist[u]:
                dist[u] = dist[v] + w
                updated = True
        if not updated:
            break
    return dist

