    # 检查可达性
    from collections import deque
    def can_reach(start, target):
        visited = [False]*(n+1)
        q = deque([start])
        visited[start] = True
        while q:
            u = q.popleft()
            if u == target: return True
            for v in graph[u]:
                if not visited[v]:
                    visited[v] = True
                    q.append(v)
        return False

    if not can_reach(s, t):
        print("UNREACHABLE")
        return

    # Bellman-Ford
    INF = 10**18
    dist = [INF]*(n+1)
    dist[s] = 0
    for _ in range(n-1):
        updated = False
        for u, v, w in edges:
            if dist[u] != INF and dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                updated = True
        if not updated:
            break

