def solve():
    input = sys.stdin.readline
    n, m, k, E, H = map(int, input().split())
    special = set(map(int, input().split())) if k > 0 else set()
    recover = {}
    if k > 0:
        vals = list(map(int, input().split()))
        for i, room in enumerate(special):
            recover[room] = vals[i]
    graph = [[] for _ in range(n+1)]
    for _ in range(m):
        u, v, w = map(int, input().split())
        graph[u].append((v, w))

    INF = -1
    # dp[room] = max health at room
    dp = [INF] * (n+1)
    dp[1] = E
    pq = [(-E, 1)]  # max-heap using negative

    while pq:
        hp, u = heapq.heappop(pq)
        hp = -hp
        if hp < dp[u]:
            continue
        if u == n:
            continue
        for v, w in graph[u]:
            new_hp = hp - w
            if new_hp <= 0:
                continue
            if v in recover:
                new_hp = min(H, new_hp + recover[v])
            if new_hp > dp[v]:
                dp[v] = new_hp
                heapq.heappush(pq, (-new_hp, v))

    print(dp[n] if dp[n] != INF else -1)

