def solve():
    input = sys.stdin.readline
    n, m = map(int, input().split())
    graph = [[float('inf')] * (n+1) for _ in range(n+1)]
    for _ in range(m):
        u, v, w = map(int, input().split())
        graph[u][v] = min(graph[u][v], w)
        graph[v][u] = min(graph[v][u], w)
    # 由于N<=100，可以使用DP状态压缩或DFS剪枝，这里使用状态压缩DP
    # dp[mask][i] 表示已访问集合mask，当前在i的最短路径
    INF = float('inf')
    dp = [[INF] * (n+1) for _ in range(1 << n)]
    dp[1][0] = 0  # 起点0（编号1对应索引0）
    for mask in range(1 << n):
        for i in range(n):
            if dp[mask][i] == INF:
                continue
            for j in range(n):
                if mask & (1 << j):
                    continue
                if graph[i+1][j+1] != INF:
                    nmask = mask | (1 << j)
                    nd = dp[mask][i] + graph[i+1][j+1]
                    if nd < dp[nmask][j]:
                        dp[nmask][j] = nd
    ans = INF
    full = (1 << n) - 1
    for mask in range(1 << n):
        if mask & 1:  # 包含起点
            if mask & (1 << (n-1)):  # 包含终点
                ans = min(ans, dp[mask][n-1])
    print(ans if ans != INF else -1)

