import sys
def solve():
    n = int(sys.stdin.readline())
    # 贪心：从2开始取连续整数，直到剩余数小于等于最后一个数，则把剩余数分配给前面的数（尽量均分）
    parts = []
    s = 0
    cur = 2
    while s + cur <= n:
        parts.append(cur)
        s += cur
        cur += 1
    rem = n - s
    if rem > 0:
        if rem == 1 and parts:
            parts[-1] += 1
        else:
            for i in range(len(parts)-1, -1, -1):
                if rem == 0: break
                parts[i] += 1
                rem -= 1
    prod = 1
    for x in parts:
        prod *= x
    print(prod)
