N, K = map(int, input().split())
from functools import lru_cache
@lru_cache(None)
def solve(n, k):
    if n == 1: return 0
    if k == 0:
        # 贪心：偶数除2，奇数减1
        if n % 2 == 0: return 1 + solve(n//2, 0)
        else: return 1 + solve(n-1, 0)
    # 可以跳过
    best = 1 + solve(n, k-1)  # 跳过
    if n % 2 == 0:
        best = min(best, 1 + solve(n//2, k))
    else:
        best = min(best, 1 + solve(n-1, k))
    return best
print(solve(N, K))

